GRPO RLVR Recovery Training for pruned models — v3 emergency variant.

Changes from v2/base:
- Format reward: +0.1 for completions containing \boxed{}
- KL penalty via --beta (default 0.01)
- --loss_type support (default dapo)
- max_completion_length default raised to 2048
"""

import argparse
import logging
import os
import random
import re

import numpy as np
import torch
from datasets import load_dataset
from transformers import AutoTokenizer, TrainerCallback
from model_utils import load_pruned_model
from trl import GRPOConfig, GRPOTrainer

try:
    import wandb
except ImportError:
    wandb = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


class RewardDesertCallback(TrainerCallback):
    """Stop training if reward stays at zero for too many consecutive log events."""

    def __init__(self, patience: int = 50):
        self.patience = patience
        self.zero_reward_count = 0
        self.last_logged_step = -1

    def on_log(self, args, state, control, logs=None, **kwargs):
        if logs is None:
            return
        reward_mean = logs.get("reward", logs.get("rewards/mean", None))
        if reward_mean is None:
            return
        if state.global_step == self.last_logged_step:
            return
        self.last_logged_step = state.global_step

        if reward_mean == 0.0:
            self.zero_reward_count += 1
            if self.zero_reward_count >= self.patience:
                logger.warning(
                    f"REWARD DESERT: reward=0 for {self.zero_reward_count} consecutive "
                    f"log events (~{self.zero_reward_count * args.logging_steps} steps). "
                    f"Pruned model may be too weak for GRPO. Stopping."
                )
                control.should_training_stop = True
        else:
            self.zero_reward_count = 0


def extract_answer(text: str) -> str | None:
    """Extract numeric answer from model output."""
    boxed = re.findall(r"\\boxed\{([^}]+)\}", text)
    if boxed:
        return boxed[-1].strip().replace(",", "")

    hash_match = re.findall(r"####\s*(.+)", text)
    if hash_match:
        return hash_match[-1].strip().replace(",", "")

    numbers = re.findall(r"-?\d+(?:,\d{3})*(?:\.\d+)?", text)
    if numbers:
        return numbers[-1].replace(",", "")
    return None


def normalize_answer(ans: str) -> str:
    ans = ans.strip().replace(",", "").replace(" ", "")
    try:
        val = float(ans)
        if val == int(val):
            return str(int(val))
        return str(val)
    except (ValueError, OverflowError):
        return ans


def extract_gold_answer(answer_text: str) -> str:
    match = re.search(r"####\s*(.+)", answer_text)
    if match:
        return normalize_answer(match.group(1))
    return answer_text.strip()


def has_boxed_format(text: str) -> bool:
    """Check if completion contains \boxed{...} formatting."""
    return bool(re.search(r"\\boxed\{[^}]+\}", text))


def build_reward_fn(tokenizer, format_reward_weight: float = 0.1):
    """Build reward function with accuracy + format reward.

    v3: adds +format_reward_weight for completions containing \boxed{}.
    """

    def reward_fn(completions, **kwargs):
        prompts = kwargs.get("prompts", None)
        gold_answers = kwargs.get("answer", None)

        rewards = []
        for i, completion in enumerate(completions):
            if isinstance(completion, list):
                text = completion[-1]["content"] if completion else ""
            else:
                text = completion

            pred = extract_answer(text)

            if gold_answers is not None and i < len(gold_answers):
                gold = normalize_answer(str(gold_answers[i]))
            else:
                gold = None

            # Accuracy reward (primary)
            if pred is not None and gold is not None:
                pred_norm = normalize_answer(pred)
                accuracy_reward = 1.0 if pred_norm == gold else 0.0
            else:
                accuracy_reward = 0.0

            # Format reward: encourage \boxed{} usage
            fmt_reward = format_reward_weight if has_boxed_format(text) else 0.0

            rewards.append(accuracy_reward + fmt_reward)

        return rewards

    return reward_fn


def prepare_dataset(tokenizer, max_samples: int = None, seed: int = 42):
    ds = load_dataset("openai/gsm8k", "main", split="train")
    if max_samples is not None:
        ds = ds.shuffle(seed=seed).select(range(min(max_samples, len(ds))))

    def format_prompt(example):
        prompt = (
            f"Solve the following math problem step by step. "
            f"Put your final answer in \\boxed{{}}.\n\n"
            f"Question: {example['question']}\n\nAnswer:"
        )
        example["prompt"] = prompt
        example["answer"] = extract_gold_answer(example["answer"])
        return example

    ds = ds.map(format_prompt)
    return ds


def main():
    parser = argparse.ArgumentParser(description="GRPO RLVR recovery training v3 — format reward + KL penalty")
    parser.add_argument("--model_path", type=str, required=True, help="Path to pruned model")
    parser.add_argument("--output_dir", type=str, default=None)
    parser.add_argument("--gpu", type=int, default=0, help="GPU index (for logging only, use CUDA_VISIBLE_DEVICES)")
    parser.add_argument("--learning_rate", type=float, default=1e-6)
    parser.add_argument("--num_train_epochs", type=int, default=3)
    parser.add_argument("--per_device_train_batch_size", type=int, default=2)
    parser.add_argument("--gradient_accumulation_steps", type=int, default=8)
    parser.add_argument("--max_completion_length", type=int, default=2048)
    parser.add_argument("--temperature", type=float, default=0.7)
    parser.add_argument("--num_generations", type=int, default=4)
    parser.add_argument("--max_samples", type=int, default=None, help="Limit training samples (None=all)")
    parser.add_argument("--logging_steps", type=int, default=10)
    parser.add_argument("--save_steps", type=int, default=200)
    parser.add_argument("--save_total_limit", type=int, default=2)
    parser.add_argument("--reward_desert_patience", type=int, default=50)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--dtype", type=str, default="bfloat16", choices=["float16", "bfloat16", "float32"])
    parser.add_argument("--report_to", type=str, default="wandb")
    parser.add_argument("--run_name", type=str, default=None)
    parser.add_argument("--wandb_project", type=str, default="recovery_aware_struct_prune")
    # v3 additions
    parser.add_argument("--beta", type=float, default=0.01, help="KL penalty coefficient (0=no KL)")
    parser.add_argument("--loss_type", type=str, default="dapo", help="GRPO loss type (grpo, dapo, etc.)")
    parser.add_argument("--format_reward_weight", type=float, default=0.1,
                        help="Reward bonus for \\boxed{} formatting")
    args = parser.parse_args()
